20	constexpr uint32_t scenarioNum = SCENARIO_NUM;
21	
22	template <int32_t blockLength, int32_t tileLength, uint64_t mask>
23	__global__ __vector__ void cast_custom(__gm__ uint8_t* x, __gm__ uint8_t* y)
24	{
25	    AscendC::InitSocState();
26	
27	    if constexpr (scenarioNum == 0) {
28	        // 场景0：half转int4b_t
29	        AscendC::GlobalTensor<half> xGm;
30	        AscendC::GlobalTensor<int8_t> yGm;
31	        xGm.SetGlobalBuffer((__gm__ half*)x + blockLength * AscendC::GetBlockIdx(), blockLength);
32	        yGm.SetGlobalBuffer((__gm__ int8_t*)y + blockLength * AscendC::GetBlockIdx() / 2, blockLength / 2);
33	
34	        AscendC::LocalMemAllocator<AscendC::Hardware::UB> ubAllocator;
35	        AscendC::LocalTensor<half> xLocal = ubAllocator.Alloc<half, tileLength>();
36	        AscendC::LocalTensor<int8_t> yLocal = ubAllocator.Alloc<int8_t, tileLength / 2>();
37	
38	        AscendC::DataCopy(xLocal, xGm, tileLength);
39	        AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(EVENT_ID0);
40	        AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(EVENT_ID0);
41	
42	        AscendC::LocalTensor<AscendC::int4b_t> yLocalTmp = yLocal.template ReinterpretCast<AscendC::int4b_t>();
43	        AscendC::Cast<AscendC::int4b_t, half>(yLocalTmp, xLocal, AscendC::RoundMode::CAST_CEIL, mask, 4, {1, 1, 2, 8});
44	        AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(EVENT_ID0);
45	        AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(EVENT_ID0);
46	
47	        AscendC::DataCopy(yGm, yLocal, tileLength / 2);
48	    } else if constexpr (scenarioNum == 1) {
49	        // 场景1：half转int32_t
50	        AscendC::GlobalTensor<half> xGm;
51	        AscendC::GlobalTensor<int32_t> yGm;
52	        xGm.SetGlobalBuffer((__gm__ half*)x + blockLength * AscendC::GetBlockIdx(), blockLength);
53	        yGm.SetGlobalBuffer((__gm__ int32_t*)y + blockLength * AscendC::GetBlockIdx(), blockLength);
54	
55	        AscendC::LocalMemAllocator<AscendC::Hardware::UB> ubAllocator;
56	        AscendC::LocalTensor<half> xLocal = ubAllocator.Alloc<half, tileLength>();
57	        AscendC::LocalTensor<int32_t> yLocal = ubAllocator.Alloc<int32_t, tileLength>();
58	
59	        AscendC::DataCopy(xLocal, xGm, tileLength);
60	        AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(EVENT_ID0);
61	        AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(EVENT_ID0);
62	
63	        AscendC::Cast(yLocal, xLocal, AscendC::RoundMode::CAST_CEIL, tileLength);
64	        AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(EVENT_ID0);
65	        AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(EVENT_ID0);
66	
67	        AscendC::DataCopy(yGm, yLocal, tileLength);
68	    } else {
69	        AscendC::printf("scenarioNum %d is not supported!\n", scenarioNum);
70	    }
71	
72	    AscendC::PipeBarrier<PIPE_ALL>();
73	}
