79	    constexpr int32_t tileLength = blockLength;
80	    constexpr uint64_t mask = 128;
81	
82	    uint32_t numBlocks = 1;
83	    size_t inputByteSize = totalLength * sizeof(half);
84	    size_t outputByteSize = 0;
