86	        outputByteSize = totalLength * sizeof(int8_t) / 2;
87	    } else if constexpr (scenarioNum == 1) {
88	        outputByteSize = totalLength * sizeof(int32_t);
89	    }
90	
91	    int32_t deviceId = 0;
92	    aclrtSetDevice(deviceId);
93	    aclrtStream stream = nullptr;
94	    aclrtCreateStream(&stream);
95	
96	    uint8_t *xHost, *yHost;
97	    uint8_t *xDevice, *yDevice;
98	
99	    aclrtMallocHost((void**)(&xHost), inputByteSize);
100	    aclrtMallocHost((void**)(&yHost), outputByteSize);
101	    aclrtMalloc((void**)&xDevice, inputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
102	    aclrtMalloc((void**)&yDevice, outputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);
103	
104	    ReadFile("./input/input_x.bin", inputByteSize, xHost, inputByteSize);
105	    aclrtMemcpy(xDevice, inputByteSize, xHost, inputByteSize, ACL_MEMCPY_HOST_TO_DEVICE);
106	    cast_custom<blockLength, tileLength, mask><<<numBlocks, 0, stream>>>(xDevice, yDevice);
107	    aclrtSynchronizeStream(stream);
108	
109	    aclrtMemcpy(yHost, outputByteSize, yDevice, outputByteSize, ACL_MEMCPY_DEVICE_TO_HOST);
110	    WriteFile("./output/output.bin", yHost, outputByteSize);
111	
112	    aclrtFree(xDevice);
