114	    aclrtFreeHost(xHost);
115	    aclrtFreeHost(yHost);
116	
117	    aclrtDestroyStream(stream);
118	    aclrtResetDevice(deviceId);
119	    aclFinalize();
120	
121	    return 0;
122	}
